import os
import tempfile
import unittest

from kit.tests.helpers import make_repo, run_git
import common
import merge

AGENTS = "## Loop\nTest command: true\nLoop branch: loop/main\n"
PROSE = "Fixture generated with Claude Code is parsed"
MESSAGE = "\n\n".join([
    "real change",
    PROSE,
    "Generated by [Claude Code](https://claude.com/claude-code)",
    "\U0001F916 Generated with Claude Code.",
    "Claude-Session: abc",
])


class SquashFooterFormsTest(unittest.TestCase):
    def test_footer_forms_go_and_prose_about_claude_stays(self):
        with tempfile.TemporaryDirectory() as tmp:
            work, _ = make_repo(tmp, {"AGENTS.md": AGENTS, "app.py": "x = 1\n"})
            run_git(["push", "origin", "main:loop/main"], work)
            run_git(["checkout", "-b", "issue/1", "main"], work)
            with open(os.path.join(work, "app.py"), "w") as f:
                f.write("x = 2\n")
            run_git(["add", "-A"], work)
            run_git(["commit", "-m", MESSAGE], work)
            sha = common.git(["rev-parse", "HEAD"], cwd=work)
            body = merge.squash_body(work, "loop/main", sha)
        self.assertIn("real change", body)
        self.assertIn(PROSE, body)
        self.assertNotIn("Generated by", body)
        self.assertNotIn("Generated with", body)
        self.assertNotIn("Claude-Session", body)


if __name__ == "__main__":
    unittest.main()
